//Bubble Sort
#include<iostream>
using namespace std;
void bSort(int a[], int n)
 {
    int flag = 0,temp = 0;
    for (int k =0; k < n-1;k++)
    {
        for(int m =0; m <n-1-k;m++)
        {
            if(a[m] > a[m+1])
            {
                // swap(a[m],a[m+1]);
                temp = a[m];
                a[m] = a[m+1];
                a[m+1] = temp;
                flag =1;
            }
        }
        if (flag == 0) break;
    }
 }

